const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.query) {
  errors.push('Missing required parameter: query');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    query: body.query,
    limit: body.limit || 10,
    filters: body.filters || {},
    user_id: body.user_id,
    qdrant_url: body.qdrant_url || process.env.QDRANT_URL || 'http://localhost:6333',
    qdrant_api_key: body.qdrant_api_key || process.env.QDRANT_API_KEY,
    openai_api_key: body.openai_api_key || process.env.OPENAI_API_KEY,
    collection: 'recipes'
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  if (input.error || input.status?.error) {
    return [{
      json: {
        success: false,
        error: {
          code: 500,
          message: input.error?.message || input.status?.error || 'Qdrant search failed',
          status: 'SEARCH_ERROR'
        },
        meta: { provider: 'qdrant', collection: prevData.collection }
      }
    }];
  }

  const results = (input.result || []).map(item => ({
    id: item.id,
    score: item.score,
    recipe: item.payload || {}
  }));

  // Apply filters if any
  let filtered = results;
  const filters = prevData.filters;

  if (filters.max_time_minutes) {
    filtered = filtered.filter(r => {
      const total = (r.recipe.prep_time_minutes || 0) + (r.recipe.cook_time_minutes || 0);
      return total <= filters.max_time_minutes;
    });
  }

  if (filters.vegetarian) {
    filtered = filtered.filter(r => r.recipe.tags?.includes('vegetarian') || r.recipe.tags?.includes('végétarien'));
  }

  if (filters.vegan) {
    filtered = filtered.filter(r => r.recipe.tags?.includes('vegan') || r.recipe.tags?.includes('végan'));
  }

  return [{
    json: {
      success: true,
      data: {
        results: filtered,
        total: filtered.length,
        query: prevData.query
      },
      meta: {
        provider: 'qdrant',
        collection: prevData.collection,
        query_embedding_used: true,
        original_count: results.length,
        filtered_count: filtered.length
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process search results: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'qdrant' }
    }
  }];
}
